dark.customCSS:
:root {
	--ms-glass: color-mix(in oklab, var(--color-gray-900) 56%, transparent);
	--ms-sidebar: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--ms-bubble: color-mix(in oklab, var(--ms-accent) 12%, var(--color-gray-800) 46%);
	--ms-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--ms-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--ms-glow: color-mix(in oklab, var(--ms-accent) 45%, transparent);
	--ms-ring: color-mix(in oklab, var(--ms-accent) 16%, transparent);
	--ms-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--ms-accent: oklch(0.87 0.1 98);
}

/* Midsummer night: glass in Open WebUI's own shapes, colored by the palette. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--ms-glass) !important;
	border-color: var(--ms-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--ms-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--ms-glow) !important;
	box-shadow: 0 0 0 3px var(--ms-ring), 0 12px 40px -16px var(--ms-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--ms-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--ms-line);
}
#sidebar {
	background-color: var(--ms-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--ms-line);
}
#sidebar-chat-item.selected { background-color: var(--ms-selected); }
.markdown-prose a { color: var(--ms-accent); text-decoration-color: var(--ms-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--ms-glow); }
.markdown-prose :is(h1, h2) { color: var(--ms-accent); }
.markdown-prose hr { border-color: var(--ms-glow); }
html { scrollbar-color: var(--ms-line) transparent; }
::selection { background-color: var(--ms-ring); }

dark.canvasScript:
/**
 * Title: Firefly Meadow
 * Description: Fireflies blink in short bursts over swaying grass and ground mist under a crescent moon; now and then one flashes a J-shaped mating arc, a tap sends the nearest one on its own, and the cursor turns the breeze.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const FIREFLY_COUNT  = 60;    // fireflies drifting over the meadow (5-120)
const DRIFT_SPEED    = 1;     // how fast the fireflies wander and the grass sways (0-3)
const REDUCED_SPEED  = 0.3;   // share of the motion kept under reduced motion (0-1)
const FLASH_LENGTH   = 0.14;  // how long a flash lasts, in seconds (0.05-0.6)
const DARK_MIN       = 1.5;   // shortest pause between flashes, in seconds (0.5-6)
const DARK_MAX       = 4.5;   // longest pause between flashes, in seconds (1-12)
const ARC_EVERY      = 8;     // average seconds between J-shaped mating arcs; 0 turns them off (0-60)
const GRASS_DENSITY  = 1;     // how thick the grass grows (0-2)
const GRASS_HEIGHT   = 0.15;  // tallest blades as a share of the screen height (0.05-0.2)
const WIND           = 0.5;   // strength of the breeze (0-2)
const CURSOR_WIND    = 0.5;   // how far the cursor turns the breeze; settles when it stops (0-2)
const MIST           = 0.5;   // ground mist along the grass line (0-1)
const MOON_PHASE     = 0.22;  // 0 new, 0.5 full (0-1)
const CENTER_CALM    = 0.8;   // how much everything thins behind the chat column (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band, in px (300-900)
const FOLLOW_THEME   = true;  // draw in the theme's colors
/* ──────────────────────────────────────────── */

const DEFAULT = { background: '#0b1018', surface: '#121a24', text: '#eef0e6', muted: '#7d8a99', accent: '#7fbf4d', accent2: '#ffd35c', accent3: '#3f7f57' };
const MAX_FLIES = 120, MAX_BLADES = 900, MAX_STARS = 140, TRAIL = 28, TAU = Math.PI * 2;
const F = (n) => new Float32Array(n);

let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, reduced = false, dark = true, colors = DEFAULT;
let grassStyle = [], flySprite = [], coreStyle = [], groundCache, mistSprite, moonSprite, moonGlow, starStyle = '#fff', trailStyle = '#fff';
let time = 0, wind = 0;
const fx = F(MAX_FLIES), fy = F(MAX_FLIES), fpx = F(MAX_FLIES), fpy = F(MAX_FLIES), fsz = F(MAX_FLIES);
const ftimer = F(MAX_FLIES), fdark = F(MAX_FLIES), fshade = new Uint8Array(MAX_FLIES);
let flies = 0;
const bx = F(MAX_BLADES), by = F(MAX_BLADES), bh = F(MAX_BLADES), bph = F(MAX_BLADES), bsp = F(MAX_BLADES), bsw = F(MAX_BLADES), blean = F(MAX_BLADES);
const groupStart = new Uint16Array(25);
const stx = F(MAX_STARS), sty = F(MAX_STARS), sts = F(MAX_STARS);
let starCount = 0;
// The J arc: one firefly at a time follows a curve whose control point dips below it, so it drops and then sweeps up
const arc = { fly: -1, t: 0, x0: 0, y0: 0, cx: 0, cy: 0, x1: 0, y1: 0, wait: ARC_EVERY * 0.5, fade: 0 };
const tx = F(TRAIL), ty = F(TRAIL);
let trailHead = 0, trailLen = 0;
const mouse = { x: 0, amount: 0 };

function hex(c) { const n = parseInt(c.slice(1), 16); return [(n >> 16) & 255, (n >> 8) & 255, n & 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0]) + ',' + Math.round(c[1]) + ',' + Math.round(c[2]) + ',' + a.toFixed(3) + ')'; }
function band(x) {
	const t = Math.min(1, Math.max(0, (Math.abs(x - w / 2) / BAND_WIDTH - 0.55) / 0.7));
	return 1 - t * t * (3 - 2 * t);
}
function calm(x) { return 1 - CENTER_CALM * band(x); }
function sideX() {
	for (let i = 0; i < 6; i++) { const x = Math.random() * w; if (Math.random() < calm(x)) return x; }
	return Math.random() < 0.5 ? Math.random() * w * 0.2 : w - Math.random() * w * 0.2;
}

function sprite(size, col, a0, a1) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(0.3, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

// ── Palette: precomputed ramps, rebuilt on theme change only ──
function applyTheme(t) {
	if (t) dark = t.dark !== false;
	colors = FOLLOW_THEME && t && t.colors ? t.colors : DEFAULT;
	const surface = hex(colors.surface), text = hex(colors.text), muted = hex(colors.muted);
	const a1 = hex(colors.accent), a2 = hex(colors.accent2), a3 = hex(colors.accent3), bg = hex(colors.background);
	const base = dark ? surface : mix(muted, text, 0.2);
	const amount = dark ? [0.14, 0.24, 0.36] : [0.3, 0.42, 0.55];
	for (let l = 0; l < 3; l++) for (let k = 0; k < 8; k++) {
		grassStyle[l * 8 + k] = rgba(mix(base, mix(a3, a1, k / 7), amount[l]), dark ? 0.45 + l * 0.22 : 0.22 + l * 0.14);
	}
	for (let k = 0; k < 8; k++) {
		const c = mix(a1, a2, 0.35 + k / 11);
		flySprite[k] = sprite(64, dark ? mix(c, [255, 255, 255], 0.15) : mix(c, text, 0.1), dark ? 0.9 : 0.75, dark ? 0.35 : 0.28);
		coreStyle[k] = rgba(dark ? mix(c, text, 0.55) : mix(c, text, 0.35), 1);
	}
	starStyle = rgba(dark ? text : muted, 1);
	trailStyle = rgba(dark ? mix(a2, text, 0.4) : mix(a2, text, 0.3), 1);
	mistSprite = sprite(128, dark ? muted : mix(muted, bg, 0.3), dark ? 0.35 : 0.25, 0.18);
	moonGlow = sprite(128, dark ? text : muted, dark ? 0.2 : 0.1, dark ? 0.06 : 0.03);
	moonSprite = new OffscreenCanvas(48, 48);
	const g = moonSprite.getContext('2d');
	g.fillStyle = rgba(dark ? text : muted, dark ? 0.9 : 0.7);
	g.beginPath(); g.arc(24, 24, 18, 0, TAU); g.fill();
	g.globalCompositeOperation = 'destination-out';
	const off = 36 * Math.min(1, Math.abs(MOON_PHASE - 0.5) * 2);
	g.beginPath(); g.arc(24 + (MOON_PHASE < 0.5 ? -1 : 1) * (36 - off), 23, 18.5, 0, TAU);
	g.fill();
	if (w) buildGround();
}

// Ground shade, cached: a soft band at the foot of the grass
function buildGround() {
	const gh = Math.max(1, Math.round(h * 0.12));
	groundCache = new OffscreenCanvas(Math.max(1, Math.round(w / 2)), Math.max(1, Math.round(gh / 2)));
	const g = groundCache.getContext('2d');
	const grad = g.createLinearGradient(0, 0, 0, groundCache.height);
	const c = dark ? mix(hex(colors.background), [0, 0, 0], 0.5) : mix(hex(colors.muted), hex(colors.accent3), 0.3);
	grad.addColorStop(0, rgba(c, 0));
	grad.addColorStop(1, rgba(c, dark ? 0.6 : 0.16));
	g.fillStyle = grad;
	g.fillRect(0, 0, groundCache.width, groundCache.height);
}

function resetFly(i) {
	fx[i] = sideX();
	fy[i] = h * (0.5 + Math.random() * 0.45);
	fpx[i] = Math.random() * TAU; fpy[i] = Math.random() * TAU;
	fsz[i] = 0.8 + Math.random() * 0.6;
	fdark[i] = DARK_MIN + Math.random() * (DARK_MAX - DARK_MIN);
	ftimer[i] = Math.random() * fdark[i];
	fshade[i] = Math.floor(Math.random() * 8);
}

function size() {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	flies = Math.min(MAX_FLIES, Math.round(FIREFLY_COUNT * Math.max(0.5, w / 1440)));
	for (let i = 0; i < flies; i++) resetFly(i);
	// Blades grouped by layer and shade so each group strokes as one path
	const per = Math.min(Math.floor(MAX_BLADES / 24), Math.round(w / 1440 * 12 * GRASS_DENSITY));
	let n = 0;
	for (let l = 0; l < 3; l++) for (let k = 0; k < 8; k++) {
		groupStart[l * 8 + k] = n;
		for (let j = 0; j < per; j++, n++) {
			const x = sideX(), q = 1 - 0.65 * CENTER_CALM * band(x);
			bx[n] = x;
			by[n] = h + 2 - (2 - l) * h * 0.012;
			bh[n] = h * GRASS_HEIGHT * (0.35 + Math.random() * 0.65) * (0.6 + l * 0.2) * q;
			bph[n] = Math.random() * TAU; bsp[n] = 0.5 + Math.random() * 0.5; bsw[n] = 4 + Math.random() * 8;
			blean[n] = (Math.random() - 0.5) * 0.7 * bh[n];
		}
	}
	groupStart[24] = n;
	starCount = Math.min(MAX_STARS, Math.round(w * h / 12000));
	for (let i = 0; i < starCount; i++) {
		stx[i] = Math.random() * w; sty[i] = Math.random() * h * 0.5;
		sts[i] = (0.3 + Math.random() * 0.7) * calm(stx[i]);
	}
	arc.fly = -1;
	buildGround();
}

// Starts a J arc for firefly i, heading away from the chat column
function startArc(i) {
	if (i < 0 || reduced) return;
	const dir = fx[i] < w / 2 ? -1 : 1, s = Math.min(1, h / 900);
	arc.fly = i; arc.t = 0; arc.fade = 1;
	arc.x0 = fx[i]; arc.y0 = fy[i];
	arc.cx = fx[i] + dir * 50 * s; arc.cy = fy[i] + 120 * s;
	arc.x1 = fx[i] + dir * 120 * s; arc.y1 = fy[i] - 70 * s;
	trailLen = 0;
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = DRIFT_SPEED * (reduced ? REDUCED_SPEED : 1);
	time = (time + dt * motion) % 10000;
	mouse.amount = Math.max(0, mouse.amount - dt * 0.3);
	const target = Math.sin(time * 0.21) * 0.6 * WIND + (mouse.x / w - 0.5) * 2 * CURSOR_WIND * mouse.amount;
	wind += (target - wind) * Math.min(1, dt * 1.2);
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';

	// Stars and moon, dark themes only for the stars
	if (dark) {
		ctx.fillStyle = starStyle;
		for (let i = 0; i < starCount; i++) {
			ctx.globalAlpha = sts[i] * (0.35 + 0.3 * Math.sin(now / 1000 * (0.4 + (i % 7) * 0.15) + i));
			ctx.fillRect(stx[i], sty[i], 1.2, 1.2);
		}
	}
	const mx = w * 0.84, my = h * 0.17;
	ctx.globalAlpha = 1;
	ctx.drawImage(moonGlow, mx - 110, my - 110, 220, 220);
	ctx.drawImage(moonSprite, mx - 24, my - 24, 48, 48);

	ctx.globalAlpha = 1;
	if (groundCache) ctx.drawImage(groundCache, 0, h - h * 0.12, w, h * 0.12);

	// Grass, far to near, mist after the far layers
	ctx.lineCap = 'round';
	for (let l = 0; l < 3; l++) {
		ctx.lineWidth = 1 + l * 0.5;
		const lw = wind * (0.5 + l * 0.25);
		for (let k = 0; k < 8; k++) {
			const g = l * 8 + k, end = groupStart[g + 1];
			if (end === groupStart[g]) continue;
			ctx.strokeStyle = grassStyle[g];
			ctx.beginPath();
			for (let i = groupStart[g]; i < end; i++) {
				const sway = (Math.sin(time * bsp[i] + bph[i]) * 0.6 + lw) * bsw[i];
				ctx.moveTo(bx[i], by[i]);
				ctx.quadraticCurveTo(bx[i] + blean[i] * 0.15 + sway * 0.3, by[i] - bh[i] * 0.55, bx[i] + blean[i] + sway, by[i] - bh[i] + Math.abs(blean[i]) * 0.3);
			}
			ctx.stroke();
		}
		if (l === 1 && MIST > 0) {
			const breathe = 0.6 + 0.4 * Math.sin(time * 0.15);
			for (let m = 0; m < 9; m++) {
				const x = ((m / 9) * (w + 400) + time * 6 * (m % 2 ? 1 : -0.6)) % (w + 400) - 200;
				ctx.globalAlpha = MIST * breathe * calm(x) * (dark ? 0.9 : 0.7);
				ctx.drawImage(mistSprite, x - 180, h * 0.86 - 30 + (m % 3) * 12, 360, 70);
			}
			ctx.globalAlpha = 1;
		}
	}

	// Fireflies: wandering, blinking with a quick rise and a slower fade
	const glowOp = dark ? 'lighter' : 'source-over';
	const flash = FLASH_LENGTH * (reduced ? 4 : 1);
	for (let i = 0; i < flies; i++) {
		if (i !== arc.fly) {
			fpx[i] += dt * motion * (0.3 + (i % 5) * 0.06);
			fpy[i] += dt * motion * (0.25 + (i % 3) * 0.07);
			fx[i] += (Math.cos(fpx[i]) * 18 + wind * 6) * dt * motion;
			fy[i] += Math.sin(fpy[i]) * 10 * dt * motion;
			if (fx[i] < -30) fx[i] = w + 30; else if (fx[i] > w + 30) fx[i] = -30;
			if (fy[i] < h * 0.45) fy[i] += 8 * dt; else if (fy[i] > h * 0.97) fy[i] -= 8 * dt;
		}
		ftimer[i] += dt;
		if (ftimer[i] > fdark[i] + flash) { ftimer[i] = 0; fdark[i] = DARK_MIN + Math.random() * (DARK_MAX - DARK_MIN); }
		const ft = (ftimer[i] - fdark[i]) / flash;
		let b = ft < 0 ? 0 : ft < 0.3 ? ft / 0.3 : 1 - (ft - 0.3) / 0.7;
		if (i === arc.fly) b = Math.max(b, arc.t < 0.85 ? 1 : 0);
		const c = calm(fx[i]), s = fsz[i];
		ctx.globalCompositeOperation = glowOp;
		ctx.globalAlpha = (0.1 + b * 0.9) * c;
		const r = 22 * s * (0.45 + b * 0.55);
		ctx.drawImage(flySprite[fshade[i]], fx[i] - r, fy[i] - r, r * 2, r * 2);
		ctx.globalCompositeOperation = 'source-over';
		ctx.globalAlpha = (0.12 + b * 0.85) * c;
		ctx.fillStyle = coreStyle[fshade[i]];
		ctx.fillRect(fx[i] - s, fy[i] - s, s * 2, s * 2);
	}

	// The J arc and its fading streak of light
	if (ARC_EVERY > 0 && !reduced && arc.fly < 0) {
		arc.wait -= dt;
		if (arc.wait <= 0) {
			arc.wait = ARC_EVERY * (0.5 + Math.random());
			let pick = -1;
			for (let tries = 0; tries < 8 && pick < 0; tries++) { const i = Math.floor(Math.random() * flies); if (band(fx[i]) < 0.3) pick = i; }
			startArc(pick);
		}
	}
	if (arc.fly >= 0) {
		const i = arc.fly;
		arc.t += dt / 1.1;
		const u = Math.min(1, arc.t), v = 1 - u;
		fx[i] = v * v * arc.x0 + 2 * v * u * arc.cx + u * u * arc.x1;
		fy[i] = v * v * arc.y0 + 2 * v * u * arc.cy + u * u * arc.y1;
		if (arc.t < 0.85) { tx[trailHead] = fx[i]; ty[trailHead] = fy[i]; trailHead = (trailHead + 1) % TRAIL; trailLen = Math.min(TRAIL, trailLen + 1); }
		else arc.fade = Math.max(0, arc.fade - dt * 1.6);
		if (arc.t >= 1 && arc.fade <= 0) { arc.fly = -1; trailLen = 0; }
	}
	if (trailLen > 1) {
		ctx.strokeStyle = trailStyle;
		ctx.lineWidth = 2;
		const c = calm(arc.x0) * arc.fade * (dark ? 0.8 : 0.6);
		for (let k = 1; k < trailLen; k++) {
			const a = (trailHead - trailLen + k - 1 + TRAIL) % TRAIL, b = (a + 1) % TRAIL;
			ctx.globalAlpha = c * (k / trailLen);
			ctx.beginPath();
			ctx.moveTo(tx[a], ty[a]);
			ctx.lineTo(tx[b], ty[b]);
			ctx.stroke();
		}
	}
	ctx.globalAlpha = 1;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 2);
			if (canvas) size();
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
		case 'mousedown': {
			// A tap sends the nearest firefly outside the chat column on a J arc
			if (arc.fly >= 0) break;
			let best = -1, bd = 1e12;
			for (let i = 0; i < flies; i++) {
				if (band(fx[i]) > 0.3) continue;
				const dx = fx[i] - d.x, dy = fy[i] - d.y, dd = dx * dx + dy * dy;
				if (dd < bd) { bd = dd; best = i; }
			}
			startArc(best);
			break;
		}
	}
};

light.customCSS:
:root {
	--ms-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--ms-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--ms-bubble: color-mix(in oklab, var(--ms-accent) 10%, var(--color-gray-100) 58%);
	--ms-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--ms-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--ms-glow: color-mix(in oklab, var(--ms-accent) 50%, transparent);
	--ms-ring: color-mix(in oklab, var(--ms-accent) 18%, transparent);
	--ms-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--ms-accent: oklch(0.47 0.1 140);
}

/* Midsummer day: glass in Open WebUI's own shapes, colored by the palette. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--ms-glass) !important;
	border-color: var(--ms-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--ms-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--ms-glow) !important;
	box-shadow: 0 0 0 3px var(--ms-ring), 0 12px 40px -16px var(--ms-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--ms-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--ms-line);
}
#sidebar {
	background-color: var(--ms-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--ms-line);
}
#sidebar-chat-item.selected { background-color: var(--ms-selected); }
.markdown-prose a { color: var(--ms-accent); text-decoration-color: var(--ms-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--ms-glow); }
.markdown-prose :is(h1, h2) { color: var(--ms-accent); }
.markdown-prose hr { border-color: var(--ms-glow); }
html { scrollbar-color: var(--ms-line) transparent; }
::selection { background-color: var(--ms-ring); }

light.canvasScript:
/**
 * Title: Living Sky
 * Description: Follows your local time: the sun or a phase-correct moon rides an arc in an outer third over layered mountains, with horizon glow, drifting clouds, night stars and a theme tint.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const PREVIEW_CYCLE  = 0;     // seconds per preview day; 0 follows the clock (0-600)
const THEME_TINT     = 0.35;  // how far the sky leans toward the theme (0-1)
const ARC_X          = 0.93;  // where the sun and moon ride, share of the width (0-1)
const BODY_SIZE      = 22;    // sun and moon radius, in px (10-50)
const CLOUD_AMOUNT   = 1;     // how many clouds drift by (0-2)
const CLOUD_SPEED    = 10;    // cloud drift, in px per second (0-60)
const REDUCED_SPEED  = 0.2;   // drift kept under reduced motion (0-1)
const STAR_DENSITY   = 1;     // night stars, dark themes only (0-2)
const SHOOTING_EVERY = 45;    // average seconds between shooting stars; 0 off (0-300)
const TERRAIN_HEIGHT = 0.17;  // mountain height, share of the screen (0.05-0.2)
const PARALLAX       = 10;    // mountain shift with the cursor, in px (0-40)
const GLOW           = 1;     // horizon and zenith glow (0-2)
const CENTER_CALM    = 0.8;   // how much the sky quiets behind the chat (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band, in px (300-900)
const FOLLOW_THEME   = true;  // lean the palette toward the theme
/* ──────────────────────────────────────────── */

const MAX_STARS = 260, MAX_CLOUDS = 12, PUFFS = 6, TAU = Math.PI * 2;

let canvas, ctx, w = 0, h = 0, last = 0, reduced = false, dark = true;
let theme = null, hour = 12, clock = 0, refreshAt = 0, elapsed = 0;
let glowCache, glowG, sunSprite, moonSprite, moonHalo, haloSprite, twiSprite, cloudSprite, layers = [], layerG = [];
let starStyle = '', day = 1, twilight = 0, night = 0;
const F = (n) => new Float32Array(n);
const sx = F(MAX_STARS), sy = F(MAX_STARS), sp = F(MAX_STARS), sph = F(MAX_STARS);
const cx = F(MAX_CLOUDS), cy = F(MAX_CLOUDS), cs = F(MAX_CLOUDS), cv = F(MAX_CLOUDS);
const pox = F(MAX_CLOUDS * PUFFS), poy = F(MAX_CLOUDS * PUFFS), pr = F(MAX_CLOUDS * PUFFS);
let stars = 0, clouds = 0;
const shoot = { age: 9, x: 0, y: 0, vx: 0, vy: 120, wait: 20 };
const mouse = { x: 0, amount: 0, off: 0 };

// Atmosphere colors (0-1) for the analytic sky model
const NIGHT_ZEN = [0.015, 0.03, 0.08], NIGHT_HOR = [0.05, 0.06, 0.14];
const DAY_ZEN = [0.2, 0.45, 0.85], DAY_HOR = [0.65, 0.82, 1];
const TWI_ZEN = [0.28, 0.16, 0.38], TWI_HOR = [0.95, 0.45, 0.32];

function hex(c) { const n = parseInt(c.slice(1), 16); return [((n >> 16) & 255) / 255, ((n >> 8) & 255) / 255, (n & 255) / 255]; }
function mix(a, b, t) { return [a[0] + (b[0] - a[0]) * t, a[1] + (b[1] - a[1]) * t, a[2] + (b[2] - a[2]) * t]; }
function rgba(c, a) { return 'rgba(' + Math.round(c[0] * 255) + ',' + Math.round(c[1] * 255) + ',' + Math.round(c[2] * 255) + ',' + a.toFixed(3) + ')'; }
function smooth(a, b, x) { const t = Math.min(1, Math.max(0, (x - a) / (b - a))); return t * t * (3 - 2 * t); }
function band(x) { return 1 - smooth(0.55, 1.25, Math.abs(x - w / 2) / BAND_WIDTH); }
function calm(x) { return 1 - CENTER_CALM * band(x); }
function ridge(v) { const r = 1 - Math.abs(Math.sin(v)); return r * r; }

function sprite(size, col, a0, a1, disc) {
	const c = new OffscreenCanvas(size, size), g = c.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	grad.addColorStop(0, rgba(col, a0));
	grad.addColorStop(disc ? 0.86 : 0.35, rgba(col, a1));
	grad.addColorStop(1, rgba(col, 0));
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return c;
}

function currentHour() {
	if (PREVIEW_CYCLE) return (elapsed / PREVIEW_CYCLE * 24 + 6) % 24;
	const d = new Date();
	return d.getHours() + d.getMinutes() / 60 + d.getSeconds() / 3600;
}

// Moon phase: 0 new, 0.5 full
function moonPhase() {
	return (Date.now() - Date.UTC(2000, 0, 6, 18, 14)) / 86400000 % 29.530588 / 29.530588;
}

// ── Palette: rebuilt as the hour moves on, and on theme or size changes ──
function refresh() {
	const sunH = Math.sin((hour - 6) / 12 * Math.PI);
	day = smooth(-0.12, 0.18, sunH);
	twilight = Math.exp(-Math.pow(sunH * 3.5, 2));
	night = 1 - smooth(-0.2, 0.05, sunH);
	let zen = mix(mix(NIGHT_ZEN, DAY_ZEN, day), TWI_ZEN, twilight * 0.55);
	let hor = mix(mix(NIGHT_HOR, DAY_HOR, day), TWI_HOR, twilight * 0.85);
	let cloud = mix(mix([0.55, 0.58, 0.68], [1, 0.96, 0.92], day), TWI_HOR, twilight * 0.6);
	let sun = mix([1, 0.5, 0.2], [1, 0.88, 0.6], day);
	let ink = dark ? [0.02, 0.02, 0.04] : [0.15, 0.17, 0.2];
	if (FOLLOW_THEME && theme && theme.colors) {
		const c = theme.colors, k = THEME_TINT;
		zen = mix(zen, hex(c.accent3), k);
		hor = mix(hor, hex(c.accent), k * 0.8);
		cloud = mix(cloud, hex(dark ? c.text : c.muted), k);
		sun = mix(sun, hex(c.accent2), k * 0.4);
		ink = mix(hex(c.background), dark ? [0, 0, 0] : hex(c.text), dark ? 0.55 : 0.7);
	}
	const a = dark ? 1 : 0.6;
	sunSprite = sprite(64, dark ? mix(sun, [1, 1, 1], 0.2) : mix(sun, [1, 0.55, 0.15], 0.45), 1, 0.95, true);
	haloSprite = sprite(128, sun, 0.6 * a, 0.16 * a);
	moonHalo = sprite(64, dark ? [0.75, 0.82, 1] : [0.45, 0.5, 0.62], 0.4 * a, 0.1 * a);
	twiSprite = sprite(128, TWI_HOR, 0.55 * a, 0.2 * a);
	cloudSprite = sprite(96, dark ? cloud : mix(hor, ink, 0.3), (dark ? 0.32 : 0.16) * (0.4 + 0.6 * day + 0.4 * twilight), dark ? 0.12 : 0.06);
	starStyle = rgba(mix([1, 1, 1], hor, 0.25), 1);
	buildMoon();

	// Horizon and zenith glow, at quarter size since it is soft
	const gw = glowCache.width, gh = glowCache.height;
	glowG.globalCompositeOperation = 'source-over';
	glowG.clearRect(0, 0, gw, gh);
	const ga = GLOW * (dark ? 0.42 : 0.24);
	const hy = gh * (1 - TERRAIN_HEIGHT * 0.45);
	let grad = glowG.createLinearGradient(0, hy, 0, gh * 0.35);
	grad.addColorStop(0, rgba(hor, Math.min(1, ga)));
	grad.addColorStop(0.3, rgba(hor, Math.min(1, ga * 0.5)));
	grad.addColorStop(1, rgba(hor, 0));
	glowG.fillStyle = grad;
	glowG.fillRect(0, gh * 0.35, gw, gh * 0.65);
	grad = glowG.createLinearGradient(0, 0, 0, gh * 0.28);
	grad.addColorStop(0, rgba(zen, Math.min(1, ga * (0.4 + 0.5 * day))));
	grad.addColorStop(1, rgba(zen, 0));
	glowG.fillStyle = grad;
	glowG.fillRect(0, 0, gw, gh * 0.28);
	glowG.globalCompositeOperation = 'destination-out';
	grad = glowG.createLinearGradient(0, 0, gw, 0);
	const s = gw / Math.max(1, w), mid = gw / 2;
	const inner = BAND_WIDTH * 0.55 * s, outer = BAND_WIDTH * 1.25 * s;
	const cut = rgba([0, 0, 0], CENTER_CALM * 0.75), none = 'rgba(0,0,0,0)';
	grad.addColorStop(Math.max(0, (mid - outer) / gw), none);
	grad.addColorStop(Math.max(0, (mid - inner) / gw), cut);
	grad.addColorStop(Math.min(1, (mid + inner) / gw), cut);
	grad.addColorStop(Math.min(1, (mid + outer) / gw), none);
	glowG.fillStyle = grad;
	glowG.fillRect(0, 0, gw, gh);

	// Mountains: three ridges, hazier toward the back, lower behind the column
	for (let l = 0; l < 3; l++) {
		const g = layerG[l], lw = layers[l].width;
		g.clearRect(0, 0, lw, h);
		const depth = l / 2;
		g.fillStyle = rgba(mix(hor, ink, dark ? 0.55 + depth * 0.4 : 0.35 + depth * 0.4), 1);
		g.globalAlpha = dark ? 0.7 + depth * 0.3 : 0.22 + depth * 0.2;
		const top = h * TERRAIN_HEIGHT * (1 - depth * 0.45);
		g.beginPath();
		g.moveTo(0, h);
		for (let x = 0; x <= lw; x += 6) {
			const u = x / (230 - l * 50) + l * 7.3;
			const n = ridge(u) * 0.6 + ridge(u * 2.2 + 1.7) * 0.3 + ridge(u * 4.7 + 3) * 0.1;
			const env = 0.55 + 0.45 * Math.sin(x / 410 + l * 2.1);
			const sag = 1 - 0.7 * CENTER_CALM * band(x - PARALLAX * 2);
			g.lineTo(x, h - top * (0.4 + 1.1 * n * env) * sag);
		}
		g.lineTo(lw, h);
		g.closePath();
		g.fill();
	}
}

function buildMoon() {
	const size = 64, r = 26, m = 32;
	moonSprite = new OffscreenCanvas(size, size);
	const g = moonSprite.getContext('2d');
	const lit = dark ? [0.93, 0.93, 0.88] : [0.55, 0.58, 0.65];
	g.fillStyle = rgba(lit, 0.16);
	g.beginPath(); g.arc(m, m, r, 0, TAU); g.fill();
	const p = moonPhase(), off = r * 2 * Math.min(1, Math.abs(p - 0.5) * 2);
	const lc = new OffscreenCanvas(size, size), lg = lc.getContext('2d');
	lg.fillStyle = rgba(lit, 0.95);
	lg.beginPath(); lg.arc(m, m, r, 0, TAU); lg.fill();
	lg.globalCompositeOperation = 'destination-out';
	lg.beginPath(); lg.arc(m + (p < 0.5 ? -1 : 1) * (r * 2 - off), m, r * 1.02, 0, TAU); lg.fill();
	g.drawImage(lc, 0, 0);
}

function size() {
	const px = (v) => Math.max(1, Math.round(v));
	canvas.width = px(w);
	canvas.height = px(h);
	glowCache = new OffscreenCanvas(px(w / 4), px(h / 4));
	glowG = glowCache.getContext('2d');
	for (let l = 0; l < 3; l++) {
		layers[l] = new OffscreenCanvas(px(w + PARALLAX * 4), px(h));
		layerG[l] = layers[l].getContext('2d');
	}
	stars = Math.min(MAX_STARS, Math.round(w * h / 6000 * STAR_DENSITY));
	for (let i = 0; i < stars; i++) {
		sx[i] = Math.random() * w; sy[i] = Math.pow(Math.random(), 1.3) * h * 0.72;
		sp[i] = 0.4 + Math.random() * 1.4; sph[i] = Math.random() * TAU;
	}
	clouds = Math.min(MAX_CLOUDS, Math.round(7 * CLOUD_AMOUNT * Math.max(0.6, w / 1440)));
	for (let i = 0; i < clouds; i++) {
		cx[i] = Math.random() * (w + 600) - 300; cy[i] = h * (0.06 + Math.random() * 0.34);
		cs[i] = 0.6 + Math.random() * 0.8; cv[i] = 0.6 + Math.random() * 0.8;
		for (let j = 0; j < PUFFS; j++) {
			const k = i * PUFFS + j, q = j / (PUFFS - 1), hump = Math.sin(q * Math.PI);
			pox[k] = (q - 0.5) * 180 + (Math.random() - 0.5) * 40;
			poy[k] = (Math.random() - 0.5) * 18 - hump * 14;
			pr[k] = 34 + Math.random() * 26 + hump * 22;
		}
	}
	refresh();
}

function body(f, haloA, halo, hr, disc, dr, discA) {
	const hz = h * (1 - TERRAIN_HEIGHT * 0.55);
	const x = ARC_X * w + (f - 0.5) * 2 * Math.min(w * 0.11, 180);
	const y = hz - Math.sin(Math.min(1, Math.max(0, f)) * Math.PI) * (hz - h * 0.12);
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	ctx.globalAlpha = haloA;
	ctx.drawImage(halo, x - hr, y - hr, hr * 2, hr * 2);
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = discA;
	ctx.drawImage(disc, x - dr, y - dr, dr * 2, dr * 2);
	return x;
}

function frame(now) {
	requestAnimationFrame(frame);
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	if (!w || !h) return;
	const motion = reduced ? REDUCED_SPEED : 1;
	elapsed += dt * motion;
	clock -= dt;
	if (clock <= 0) {
		const step = PREVIEW_CYCLE ? 0.05 : 1;
		clock = step; hour = currentHour(); refreshAt -= step;
		if (refreshAt <= 0) { refresh(); refreshAt = PREVIEW_CYCLE ? 0.25 : 60; }
	}
	const t = now / 1000;
	ctx.clearRect(0, 0, w, h);
	ctx.globalCompositeOperation = 'source-over';
	ctx.globalAlpha = 1;
	ctx.drawImage(glowCache, 0, 0, w, h);

	const horizon = h * (1 - TERRAIN_HEIGHT * 0.55);

	// Stars, dark themes only, fading with daylight
	if (dark && night > 0.02) {
		ctx.fillStyle = starStyle;
		for (let i = 0; i < stars; i++) {
			const tw = 0.55 + 0.45 * Math.sin(t * sp[i] * (reduced ? 0.3 : 1) + sph[i]);
			ctx.globalAlpha = night * tw * 0.75 * calm(sx[i]) * (1 - sy[i] / h);
			ctx.fillRect(sx[i], sy[i], i % 8 ? 1 : 2, i % 8 ? 1 : 2);
		}
		if (SHOOTING_EVERY > 0 && !reduced) {
			shoot.wait -= dt;
			if (shoot.wait <= 0 && night > 0.6) {
				const side = Math.random() < 0.5 ? -1 : 1;
				shoot.x = w / 2 + side * (BAND_WIDTH + Math.random() * w * 0.2); shoot.y = h * (0.05 + Math.random() * 0.25);
				shoot.vx = side * (260 + Math.random() * 200); shoot.vy = 120;
				shoot.age = 0; shoot.wait = SHOOTING_EVERY * (0.5 + Math.random());
			}
			if (shoot.age < 0.9) {
				shoot.age += dt;
				shoot.x += shoot.vx * dt; shoot.y += shoot.vy * dt;
				ctx.globalAlpha = Math.sin(Math.PI * shoot.age / 0.9) * 0.7 * night * calm(shoot.x);
				ctx.strokeStyle = starStyle;
				ctx.beginPath(); ctx.moveTo(shoot.x, shoot.y); ctx.lineTo(shoot.x - shoot.vx * 0.12, shoot.y - shoot.vy * 0.12); ctx.stroke();
			}
		}
	}

	// Sun, or the moon at night, on an arc inside the outer third
	const sunF = (hour - 6) / 12, moonF = ((hour < 12 ? hour + 24 : hour) - 18) / 12;
	const sunVis = smooth(-0.04, 0.04, sunF) * smooth(1.04, 0.96, sunF);
	const moonVis = smooth(-0.04, 0.06, moonF) * smooth(1.04, 0.94, moonF) * (1 - day * 0.8);
	if (sunVis > 0) {
		const x = body(sunF, sunVis * (0.6 + 0.4 * twilight), haloSprite, BODY_SIZE * 10, sunSprite, BODY_SIZE, sunVis * (dark ? 0.95 : 0.85));
		ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
		ctx.globalAlpha = twilight * sunVis;
		ctx.drawImage(twiSprite, x - w * 0.22, horizon - h * 0.12, w * 0.44, h * 0.24);
		ctx.globalCompositeOperation = 'source-over';
	}
	if (moonVis > 0) body(moonF, moonVis * 0.6, moonHalo, BODY_SIZE * 4.5, moonSprite, BODY_SIZE * 1.1, moonVis);

	// Clouds: sprite puffs, thinner over the column
	const drift = CLOUD_SPEED * motion * dt;
	for (let i = 0; i < clouds; i++) {
		cx[i] += drift * cv[i];
		if (cx[i] > w + 300) { cx[i] = -300; cy[i] = h * (0.06 + Math.random() * 0.34); }
		const s = cs[i];
		for (let j = 0; j < PUFFS; j++) {
			const k = i * PUFFS + j, x = cx[i] + pox[k] * s, r = pr[k] * s;
			ctx.globalAlpha = calm(x);
			ctx.drawImage(cloudSprite, x - r * 1.3, cy[i] + poy[k] * s - r * 0.7, r * 2.6, r * 1.4);
		}
	}

	// Mountains, with a parallax that settles when the cursor stops
	mouse.amount = Math.max(0, mouse.amount - dt * 0.35);
	const target = (mouse.x / Math.max(1, w) - 0.5) * 2 * mouse.amount * (reduced ? 0.3 : 1);
	mouse.off += (target - mouse.off) * Math.min(1, dt * 2);
	ctx.globalAlpha = 1;
	for (let l = 0; l < 3; l++) ctx.drawImage(layers[l], -PARALLAX * 2 - mouse.off * PARALLAX * (0.4 + l * 0.6), 0);
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height;
			reduced = !!d.reducedMotion;
			theme = d.theme;
			dark = !theme || theme.dark !== false;
			hour = currentHour();
			size();
			requestAnimationFrame(frame);
			break;
		case 'resize':
			w = d.width; h = d.height;
			if (canvas) size();
			break;
		case 'theme':
			theme = d;
			dark = d.dark !== false;
			if (glowCache) refresh();
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.amount = 1;
			break;
	}
};

oled.customCSS:
:root {
	--ms-glass: color-mix(in oklab, var(--color-gray-950) 62%, transparent);
	--ms-sidebar: color-mix(in oklab, var(--color-gray-950) 76%, transparent);
	--ms-bubble: color-mix(in oklab, var(--ms-accent) 12%, var(--color-gray-800) 50%);
	--ms-selected: color-mix(in oklab, var(--color-gray-500) 20%, transparent);
	--ms-line: color-mix(in oklab, var(--color-gray-400) 20%, transparent);
	--ms-glow: color-mix(in oklab, var(--ms-accent) 45%, transparent);
	--ms-ring: color-mix(in oklab, var(--ms-accent) 16%, transparent);
	--ms-shade: color-mix(in oklab, var(--color-gray-950) 70%, transparent);
	--ms-accent: oklch(0.84 0.06 262);
}

/* Deep night: glass in Open WebUI's own shapes, colored by the palette. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--ms-glass) !important;
	border-color: var(--ms-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--ms-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--ms-glow) !important;
	box-shadow: 0 0 0 3px var(--ms-ring), 0 12px 40px -16px var(--ms-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--ms-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--ms-line);
}
#sidebar {
	background-color: var(--ms-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--ms-line);
}
#sidebar-chat-item.selected { background-color: var(--ms-selected); }
.markdown-prose a { color: var(--ms-accent); text-decoration-color: var(--ms-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--ms-glow); }
.markdown-prose :is(h1, h2) { color: var(--ms-accent); }
.markdown-prose hr { border-color: var(--ms-glow); }
html { scrollbar-color: var(--ms-line) transparent; }
::selection { background-color: var(--ms-ring); }

oled.canvasScript:
/**
 * Title: Constellation Map
 * Description: Drifting, twinkling stars in your theme's colors link into faint constellations, thin behind the chat, lean gently toward the cursor and light up where you tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const STAR_COUNT     = 120;   // number of stars (40-300)
const STAR_SIZE      = 1;     // size of the stars (0.5-2)
const LINK_DIST      = 150;   // longest constellation line, in px (60-260)
const LINK_ALPHA     = 0.3;   // strength of the constellation lines (0-1)
const MAX_LINKS      = 3;     // lines each star may start (1-6)
const DRIFT          = 1;     // drift speed of the stars; 0 holds them still (0-3)
const REDUCED_SPEED  = 0.2;   // share of the drift kept when the viewer asks to reduce motion (0-1)
const TWINKLE        = 1;     // how much the stars twinkle (0-2)
const CENTER_CALM    = 0.85;   // how much the stars and lines fade behind the chat column (0-1)
const BAND_WIDTH     = 520;   // half-width of the calm band around the chat column, in px (300-900)
const CURSOR_GRAVITY = 1;     // how strongly nearby stars lean toward the cursor (0-3)
const CURSOR_RADIUS  = 250;   // reach of the cursor, in px (100-400)
const MAX_PULL       = 40;    // top speed the cursor can give a star, in px per second (5-120)
const TAP_GLOW       = 1;     // how brightly a tap lights the nearby stars; 0 turns it off (0-2)
const FOLLOW_THEME   = true;  // take the colors from the theme's palette
const STAR_COLOR     = '#dce6ff';  // most stars when not following the theme
const WARM_COLOR     = '#fff0c8';  // warm stars
const BLUE_COLOR     = '#a8c4ff';  // blue stars
const LINE_COLOR     = '#b4c8ff';  // constellation lines
const CURSOR_COLOR   = '#a0c8ff';  // lines to the cursor
/* ──────────────────────────────────────────── */

const MAX_STARS = 300;
const N = Math.max(1, Math.min(MAX_STARS, Math.round(STAR_COUNT)));
const LEVELS = 6;              // line alphas are batched into this many strokes
const CAP = N * 6;             // segments per batch
const SPRITE = 64;             // star sprite size in device px

let canvas, ctx;
let w = 0, h = 0, dpr = 1;
let last = 0, time = 0, reduced = false, dark = true;
const mouse = { x: -10000, y: -10000, amount: 0, target: 0 };
const tap = { x: -10000, y: -10000, age: 10 };

const sx = new Float32Array(N), sy = new Float32Array(N);
const vx = new Float32Array(N), vy = new Float32Array(N);
const bx = new Float32Array(N), by = new Float32Array(N);
const size = new Float32Array(N), bright = new Float32Array(N);
const twRate = new Float32Array(N), twPhase = new Float32Array(N), twAmt = new Float32Array(N);
const tone = new Uint8Array(N);
const lum = new Float32Array(N);       // brightness this frame, calm included
const segs = new Float32Array(2 * LEVELS * CAP * 4);
const segN = new Int32Array(2 * LEVELS);

let colors = { stars: [STAR_COLOR, WARM_COLOR, BLUE_COLOR].map(hexToRgb), line: hexToRgb(LINE_COLOR), cursor: hexToRgb(CURSOR_COLOR) };
const sprites = [];
const styles = [];                      // [batch] -> stroke color string

function hexToRgb(hex) {
	const n = parseInt(String(hex).slice(1, 7), 16) || 0;
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}

function rgba(c, a) {
	return 'rgba(' + c[0] + ',' + c[1] + ',' + c[2] + ',' + a.toFixed(3) + ')';
}

function calm(x) {
	const d = Math.abs(x - w * 0.5) / BAND_WIDTH;
	const s = Math.min(1, Math.max(0, (d - 0.55) / 0.7));
	return 1 - CENTER_CALM * (1 - s * s * (3 - 2 * s));
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) {
		const c = t.colors;
		colors = {
			// Pale text-colored stars on dark; on light, gray dots would read as dust, so the accents lead
			stars: dark ? [hexToRgb(c.text), hexToRgb(c.accent2), hexToRgb(c.accent)] : [hexToRgb(c.accent), hexToRgb(c.accent2), hexToRgb(c.accent3)],
			line: hexToRgb(dark ? c.text : c.muted),
			cursor: hexToRgb(c.accent),
		};
	}
	build();
}

// Star sprites and line colors, rebuilt on theme change only
function build() {
	for (let k = 0; k < 3; k++) {
		const c = colors.stars[k];
		const sp = sprites[k] || new OffscreenCanvas(SPRITE, SPRITE);
		const g = sp.getContext('2d');
		g.clearRect(0, 0, SPRITE, SPRITE);
		const r = SPRITE / 2;
		const grad = g.createRadialGradient(r, r, 0, r, r, r);
		grad.addColorStop(0, rgba(c, 1));
		grad.addColorStop(0.09, rgba(c, 1));
		grad.addColorStop(0.15, rgba(c, dark ? 0.45 : 0.3));
		grad.addColorStop(0.4, rgba(c, dark ? 0.12 : 0.04));
		grad.addColorStop(1, rgba(c, 0));
		g.fillStyle = grad;
		g.fillRect(0, 0, SPRITE, SPRITE);
		sprites[k] = sp;
	}
	const top = LINK_ALPHA * (dark ? 1.3 : 1.9);
	for (let b = 0; b < LEVELS; b++) {
		styles[b] = rgba(colors.line, top * (b + 1) / LEVELS);
		styles[LEVELS + b] = rgba(colors.cursor, (dark ? 0.45 : 0.4) * (b + 1) / LEVELS);
	}
}

function seed() {
	for (let i = 0; i < N; i++) {
		sx[i] = Math.random() * w;
		sy[i] = Math.random() * h;
		const a = Math.random() * Math.PI * 2, s = 2 + Math.random() * 6;
		bx[i] = vx[i] = Math.cos(a) * s;
		by[i] = vy[i] = Math.sin(a) * s;
		size[i] = 0.8 + Math.random() * 1.8;
		bright[i] = 0.35 + Math.random() * 0.65;
		twRate[i] = 0.8 + Math.random() * 2;
		twPhase[i] = Math.random() * Math.PI * 2;
		twAmt[i] = 0.1 + Math.random() * 0.3;
		const roll = Math.random();
		tone[i] = roll < 0.6 ? 0 : roll < 0.8 ? 1 : 2;
	}
}

function size2d(nw, nh, ndpr) {
	// Keep the sky on a resize: scale the stars to the new size instead of re-rolling them
	if (w && h) {
		for (let i = 0; i < N; i++) { sx[i] *= nw / w; sy[i] *= nh / h; }
	}
	w = nw;
	h = nh;
	dpr = Math.min(2, ndpr || 1);
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
}

function addSeg(batch, x1, y1, x2, y2) {
	const n = segN[batch];
	if (n >= CAP) return;
	const o = (batch * CAP + n) * 4;
	segs[o] = x1; segs[o + 1] = y1; segs[o + 2] = x2; segs[o + 3] = y2;
	segN[batch] = n + 1;
}

function update(dt) {
	const speed = DRIFT * (reduced ? REDUCED_SPEED : 1);
	const pull = CURSOR_GRAVITY * mouse.amount * 90;
	const r2 = CURSOR_RADIUS * CURSOR_RADIUS;
	const relax = Math.min(1, dt * 0.8);
	const tw = TWINKLE * (reduced ? 0.4 : 1);
	tap.age += dt;
	const glow = TAP_GLOW * (reduced ? 0.4 : 1) * Math.min(1, tap.age * 6) * Math.max(0, 1 - tap.age / 1.8);
	for (let i = 0; i < N; i++) {
		const dx = mouse.x - sx[i], dy = mouse.y - sy[i];
		const d2 = dx * dx + dy * dy;
		if (pull > 0 && d2 < r2 && d2 > 1) {
			const d = Math.sqrt(d2);
			// Pull toward the cursor, easing to a gentle push inside 45 px so stars hover instead of piling up
			const f = pull * (1 - d / CURSOR_RADIUS) * (d < 45 ? (d - 45) / 45 : 1);
			vx[i] += dx / d * f * dt;
			vy[i] += dy / d * f * dt;
			const ex = vx[i] - bx[i], ey = vy[i] - by[i];
			const e = Math.sqrt(ex * ex + ey * ey);
			if (e > MAX_PULL) { vx[i] = bx[i] + ex / e * MAX_PULL; vy[i] = by[i] + ey / e * MAX_PULL; }
		}
		vx[i] += (bx[i] - vx[i]) * relax;
		vy[i] += (by[i] - vy[i]) * relax;
		sx[i] += vx[i] * dt * speed;
		sy[i] += vy[i] * dt * speed;
		if (sx[i] < -20) sx[i] += w + 40; else if (sx[i] > w + 20) sx[i] -= w + 40;
		if (sy[i] < -20) sy[i] += h + 40; else if (sy[i] > h + 20) sy[i] -= h + 40;
		let b = bright[i] + Math.sin(time * twRate[i] + twPhase[i]) * twAmt[i] * tw;
		if (glow > 0) {
			const tx = sx[i] - tap.x, ty = sy[i] - tap.y;
			b += glow * 0.8 * Math.max(0, 1 - Math.sqrt(tx * tx + ty * ty) / 200);
		}
		lum[i] = Math.max(0.08, Math.min(1, b)) * calm(sx[i]);
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	if (!ctx) return;
	const dt = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	time += dt * (reduced ? REDUCED_SPEED : 1);
	mouse.target = Math.max(0, mouse.target - dt * 0.5);
	mouse.amount += (mouse.target - mouse.amount) * Math.min(1, dt * 3);
	update(dt);

	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
	ctx.clearRect(0, 0, w, h);

	// Gather the lines into a few alpha batches, then stroke each batch once
	segN.fill(0);
	const link2 = LINK_DIST * LINK_DIST;
	for (let i = 0; i < N; i++) {
		let links = 0;
		for (let j = i + 1; j < N && links < MAX_LINKS; j++) {
			const dx = sx[i] - sx[j], dy = sy[i] - sy[j];
			const d2 = dx * dx + dy * dy;
			if (d2 >= link2) continue;
			links++;
			const a = (1 - Math.sqrt(d2) / LINK_DIST) * Math.min(lum[i], lum[j]) * 1.4;
			const b = Math.min(LEVELS - 1, (a * LEVELS) | 0);
			if (a > 0.06) addSeg(b, sx[i], sy[i], sx[j], sy[j]);
		}
	}
	if (mouse.amount > 0.02) {
		const r = CURSOR_RADIUS * 0.6;
		for (let i = 0; i < N; i++) {
			const dx = sx[i] - mouse.x, dy = sy[i] - mouse.y;
			const d2 = dx * dx + dy * dy;
			if (d2 >= r * r) continue;
			const a = (1 - Math.sqrt(d2) / r) * mouse.amount * calm(sx[i]);
			const b = Math.min(LEVELS - 1, (a * LEVELS) | 0);
			if (a > 0.06) addSeg(LEVELS + b, mouse.x, mouse.y, sx[i], sy[i]);
		}
	}
	ctx.lineWidth = dpr > 1 ? 0.7 : 0.8;
	for (let b = 0; b < LEVELS * 2; b++) {
		const n = segN[b];
		if (!n) continue;
		ctx.strokeStyle = styles[b];
		ctx.beginPath();
		for (let k = 0; k < n; k++) {
			const o = (b * CAP + k) * 4;
			ctx.moveTo(segs[o], segs[o + 1]);
			ctx.lineTo(segs[o + 2], segs[o + 3]);
		}
		ctx.stroke();
	}

	// Stars on top, as sprites
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	const starA = dark ? 1 : 0.95;
	const grow = STAR_SIZE * (dark ? 12 : 15);
	for (let i = 0; i < N; i++) {
		const s = size[i] * grow;
		ctx.globalAlpha = lum[i] * starA;
		ctx.drawImage(sprites[tone[i]], sx[i] - s * 0.5, sy[i] - s * 0.5, s, s);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			reduced = !!d.reducedMotion;
			size2d(d.width, d.height, d.dpr);
			seed();
			applyTheme(d.theme || {});
			requestAnimationFrame(frame);
			break;
		case 'resize':
			if (ctx) size2d(d.width, d.height, d.dpr);
			break;
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			mouse.x = d.x;
			mouse.y = d.y;
			mouse.target = reduced ? 0.3 : 1;
			break;
		case 'mousedown':
			tap.x = d.x;
			tap.y = d.y;
			tap.age = 0;
			break;
	}
};

her.customCSS:
:root {
	--ms-glass: color-mix(in oklab, var(--color-gray-50) 66%, transparent);
	--ms-sidebar: color-mix(in oklab, var(--color-gray-50) 72%, transparent);
	--ms-bubble: color-mix(in oklab, var(--ms-accent) 10%, var(--color-gray-100) 58%);
	--ms-selected: color-mix(in oklab, var(--color-gray-400) 18%, transparent);
	--ms-line: color-mix(in oklab, var(--color-gray-500) 26%, transparent);
	--ms-glow: color-mix(in oklab, var(--ms-accent) 50%, transparent);
	--ms-ring: color-mix(in oklab, var(--ms-accent) 18%, transparent);
	--ms-shade: color-mix(in oklab, var(--color-gray-600) 26%, transparent);
	--ms-accent: oklch(0.5 0.11 62);
}

/* Golden hour: glass in Open WebUI's own shapes, colored by the palette. !important only where Canvas FX transparency clears a background. */
#message-input-container {
	background-color: var(--ms-glass) !important;
	border-color: var(--ms-line) !important;
	backdrop-filter: blur(20px) saturate(1.3);
	box-shadow: 0 12px 40px -16px var(--ms-shade);
	transition: border-color 0.25s ease, box-shadow 0.25s ease;
}
#message-input-container:focus-within {
	border-color: var(--ms-glow) !important;
	box-shadow: 0 0 0 3px var(--ms-ring), 0 12px 40px -16px var(--ms-shade);
}
.chat-user .rounded-3xl {
	background-color: var(--ms-bubble) !important;
	backdrop-filter: blur(12px);
	box-shadow: inset 0 0 0 1px var(--ms-line);
}
#sidebar {
	background-color: var(--ms-sidebar) !important;
	backdrop-filter: blur(24px) saturate(1.2);
	border-inline-end: 1px solid var(--ms-line);
}
#sidebar-chat-item.selected { background-color: var(--ms-selected); }
.markdown-prose a { color: var(--ms-accent); text-decoration-color: var(--ms-glow); }
.markdown-prose blockquote { border-inline-start-color: var(--ms-glow); }
.markdown-prose :is(h1, h2) { color: var(--ms-accent); }
.markdown-prose hr { border-color: var(--ms-glow); }
html { scrollbar-color: var(--ms-line) transparent; }
::selection { background-color: var(--ms-ring); }

her.canvasScript:
/**
 * Title: Ember Dream
 * Description: Campfire embers rise from the bottom of the screen in your theme's colors, cool as they climb, thin out behind the chat, scatter when the cursor sweeps past and burst from a tap.
 */

/* ────────── CONFIGURABLE VARIABLES ────────── */
const EMBER_COUNT   = 150;   // embers in the air at once (30-400)
const RISE_SPEED    = 42;    // average climb, in px per second (10-120)
const RISE_HEIGHT   = 0.55;  // how far up the screen embers climb before burning out (0.2-1)
const SWAY          = 18;    // side-to-side drift, in px per second (0-60)
const EMBER_SIZE    = 1;     // size of each ember and its glow (0.5-2)
const WISPS         = 5;     // faint flame wisps along the bottom edge (0-12)
const GLOW_POOLS    = 3;     // warm pools of firelight along the bottom (0-6)
const WIND          = 1;     // how hard a moving cursor scatters embers (0-3)
const BURST_SIZE    = 24;    // embers thrown by a tap; 0 turns taps off (0-60)
const MOTION        = 1;     // overall speed (0.2-2)
const REDUCED_SPEED = 0.25;  // speed kept when the viewer asks to reduce motion (0-1)
const CENTER_CALM   = 0.8;   // how much the embers thin out behind the chat column (0-1)
const BAND_WIDTH    = 520;   // half-width of the calm band around the chat column, in px (300-900)
const FOLLOW_THEME  = true;  // take the colors from the theme's palette
const COLOR_HOT     = '#ffd98a';  // fresh ember color when not following the theme
const COLOR_WARM    = '#ff8c3a';  // ember color halfway up
const COLOR_COOL    = '#d4442a';  // dying ember and wisp color
const FIRE_WARMTH   = 0.5;   // how far theme colors lean toward firelight (0-1)
/* ──────────────────────────────────────────── */

const MAX_BURST = 150, ES = 32, GS = 128;
let canvas, ctx, w = 0, h = 0, dpr = 1, last = 0, time = 0, reduced = false, dark = true;
let calmLut = new Float32Array(1), hexes = [COLOR_HOT, COLOR_WARM, COLOR_COOL];
const emberSprites = [], mouse = { x: -10000, y: -10000, energy: 0 };
let glowSprite = null, wispSprite = null;

// Ember pool
const ex = new Float32Array(EMBER_COUNT), ey = new Float32Array(EMBER_COUNT), evx = new Float32Array(EMBER_COUNT);
const ey0 = new Float32Array(EMBER_COUNT), erise = new Float32Array(EMBER_COUNT), espd = new Float32Array(EMBER_COUNT);
const esz = new Float32Array(EMBER_COUNT), eph = new Float32Array(EMBER_COUNT), eage = new Float32Array(EMBER_COUNT);
// Burst pool
const bx = new Float32Array(MAX_BURST), by = new Float32Array(MAX_BURST), bvx = new Float32Array(MAX_BURST), bvy = new Float32Array(MAX_BURST);
const blife = new Float32Array(MAX_BURST), bsz = new Float32Array(MAX_BURST);
let bcount = 0;
// Wisps and pools
const wx = new Float32Array(12), wy = new Float32Array(12), wage = new Float32Array(12), wspan = new Float32Array(12), wsc = new Float32Array(12), wph = new Float32Array(12);
const px = new Float32Array(6), pph = new Float32Array(6);

function rgb(hex) {
	const n = parseInt(hex.slice(1), 16);
	return [(n >> 16) & 255, (n >> 8) & 255, n & 255];
}
function rgba(c, a, lift) {
	return 'rgba(' + Math.round(c[0] + (255 - c[0]) * lift) + ',' + Math.round(c[1] + (255 - c[1]) * lift) + ',' + Math.round(c[2] + (255 - c[2]) * lift) + ',' + a + ')';
}
// Leans a theme color toward its firelight default, so embers still read as embers
function mix(a, b) {
	const x = rgb(a), y = rgb(b), k = FIRE_WARMTH;
	return '#' + ((1 << 24) | (Math.round(x[0] + (y[0] - x[0]) * k) << 16) | (Math.round(x[1] + (y[1] - x[1]) * k) << 8) | Math.round(x[2] + (y[2] - x[2]) * k)).toString(16).slice(1);
}
function radial(size, stops) {
	const s = new OffscreenCanvas(size, size), g = s.getContext('2d'), r = size / 2;
	const grad = g.createRadialGradient(r, r, 0, r, r, r);
	for (let i = 0; i < stops.length; i += 2) grad.addColorStop(stops[i], stops[i + 1]);
	g.fillStyle = grad;
	g.fillRect(0, 0, size, size);
	return s;
}

// Sprites: one glowing ember per heat stage, a pool of firelight and a soft flame tongue
function buildSprites() {
	for (let i = 0; i < 3; i++) {
		const c = rgb(hexes[i]);
		emberSprites[i] = dark
			? radial(ES, [0, rgba(c, 1, 0.75 - i * 0.25), 0.07, rgba(c, 1, 0.35 - i * 0.12), 0.18, rgba(c, 0.7, 0), 0.4, rgba(c, 0.22, 0), 0.7, rgba(c, 0.05, 0), 1, rgba(c, 0, 0)])
			: radial(ES, [0, rgba(c, 1, 0), 0.16, rgba(c, 0.95, 0), 0.3, rgba(c, 0.35, 0), 0.6, rgba(c, 0.06, 0), 1, rgba(c, 0, 0)]);
	}
	const warm = rgb(hexes[1]), cool = rgb(hexes[2]);
	glowSprite = radial(GS, [0, rgba(warm, 1, 0), 0.4, rgba(warm, 0.45, 0), 1, rgba(warm, 0, 0)]);
	wispSprite = new OffscreenCanvas(64, 192);
	const g = wispSprite.getContext('2d');
	const grad = g.createLinearGradient(0, 192, 0, 0);
	grad.addColorStop(0, rgba(cool, 1, 0));
	grad.addColorStop(0.45, rgba(warm, 0.8, 0));
	grad.addColorStop(1, rgba(rgb(hexes[0]), 0, 0));
	g.fillStyle = grad;
	g.globalAlpha = 0.12;
	for (let k = 0; k < 9; k++) {
		const s = 1 - k * 0.08;
		g.beginPath();
		g.moveTo(32 - 30 * s, 192);
		g.bezierCurveTo(32 - 32 * s, 120, 32 - 6 * s, 80, 32 + 4 * s, 192 - 188 * s);
		g.bezierCurveTo(32 + 14 * s, 90, 32 + 32 * s, 130, 32 + 30 * s, 192);
		g.fill();
	}
}

function applyTheme(t) {
	if (!t) return;
	dark = t.dark !== false;
	if (FOLLOW_THEME && t.colors) hexes = [mix(t.colors.accent, COLOR_HOT), mix(t.colors.accent2, COLOR_WARM), mix(t.colors.accent3, COLOR_COOL)];
	if (ctx) buildSprites();
}

function calm(x) {
	const i = x >> 2;
	return calmLut[i < 0 ? 0 : i >= calmLut.length ? calmLut.length - 1 : i];
}

// Spawn in the bottom fifth, less often behind the chat column
function spawn(i, scatter) {
	let x = Math.random() * w;
	for (let k = 0; k < 3 && Math.random() > calm(x); k++) x = Math.random() * w;
	ex[i] = x;
	ey0[i] = h * (0.82 + Math.random() * 0.2);
	erise[i] = h * RISE_HEIGHT * (0.35 + Math.random() * 0.65);
	ey[i] = scatter ? ey0[i] - erise[i] * Math.random() : ey0[i];
	evx[i] = 0;
	espd[i] = RISE_SPEED * (0.6 + Math.random() * 0.8);
	esz[i] = (22 + Math.random() * 24) * EMBER_SIZE;
	eph[i] = Math.random() * 6.283;
	eage[i] = scatter ? 2 : 0;
}

function size(oldW, oldH) {
	canvas.width = Math.max(1, Math.round(w * dpr));
	canvas.height = Math.max(1, Math.round(h * dpr));
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
	calmLut = new Float32Array((w >> 2) + 2);
	for (let i = 0; i < calmLut.length; i++) {
		const t = Math.min(1, Math.max(0, (Math.abs(i * 4 - w / 2) / BAND_WIDTH - 0.55) / 0.7));
		calmLut[i] = 1 - CENTER_CALM * (1 - t * t * (3 - 2 * t));
	}
	if (oldW) {
		const sx = w / oldW, sy = h / oldH;
		for (let i = 0; i < EMBER_COUNT; i++) { ex[i] *= sx; ey[i] *= sy; ey0[i] *= sy; erise[i] *= sy; }
		for (let i = 0; i < bcount; i++) { bx[i] *= sx; by[i] *= sy; }
	} else {
		for (let i = 0; i < EMBER_COUNT; i++) spawn(i, true);
	}
	for (let i = 0; i < 12; i++) resetWisp(i, true);
	for (let i = 0; i < 6; i++) { const side = i % 2; px[i] = side ? w * (0.86 + Math.random() * 0.12) : w * (0.02 + Math.random() * 0.12); pph[i] = Math.random() * 6.283; }
}

function resetWisp(i, scatter) {
	const side = Math.random() < 0.5;
	wx[i] = side ? w * (0.03 + Math.random() * 0.25) : w * (0.72 + Math.random() * 0.25);
	wy[i] = h + 30 + Math.random() * 40;
	wspan[i] = 5 + Math.random() * 5;
	wage[i] = scatter ? Math.random() * wspan[i] : 0;
	wsc[i] = 0.6 + Math.random() * 0.7;
	wph[i] = Math.random() * 6.283;
}

function burst(x, y) {
	const n = Math.round(BURST_SIZE * Math.max(0.3, calm(x)));
	for (let k = 0; k < n && bcount < MAX_BURST; k++) {
		const i = bcount++, a = Math.random() * 6.283, v = 40 + Math.random() * 110;
		bx[i] = x; by[i] = y;
		bvx[i] = Math.cos(a) * v; bvy[i] = Math.sin(a) * v - 50;
		blife[i] = 1.2 + Math.random() * 1.2;
		bsz[i] = (20 + Math.random() * 16) * EMBER_SIZE;
	}
}

function frame(now) {
	requestAnimationFrame(frame);
	const real = last ? Math.min((now - last) / 1000, 0.1) : 0;
	last = now;
	const dt = real * MOTION * (reduced ? REDUCED_SPEED : 1);
	time += dt;
	mouse.energy *= Math.exp(-real * 2.5);
	ctx.clearRect(0, 0, w, h);
	const lit = dark ? 1 : 0.9;

	// Firelight pools and wisps along the bottom
	ctx.globalCompositeOperation = dark ? 'lighter' : 'source-over';
	for (let i = 0; i < GLOW_POOLS; i++) {
		const d = 420 + 60 * Math.sin(time * 0.4 + pph[i]);
		ctx.globalAlpha = (dark ? 0.13 : 0.05) * (0.75 + 0.25 * Math.sin(time * 0.9 + pph[i] * 3));
		ctx.drawImage(glowSprite, px[i] - d / 2, h - d * 0.32, d, d);
	}
	for (let i = 0; i < WISPS; i++) {
		wage[i] += dt;
		if (wage[i] > wspan[i]) resetWisp(i, false);
		const f = wage[i] / wspan[i], s = wsc[i];
		ctx.globalAlpha = (dark ? 0.15 : 0.06) * Math.sin(f * 3.1416) * calm(wx[i]);
		const fl = 1 + 0.12 * Math.sin(time * 5 + wph[i]), sk = 0.18 * Math.sin(time * 0.7 + wph[i]);
		ctx.setTransform(dpr * s * fl, 0, dpr * sk * s, dpr * s * (1 - f * 0.3), dpr * wx[i], dpr * (wy[i] - f * 90));
		ctx.drawImage(wispSprite, -32, -192);
	}
	ctx.setTransform(dpr, 0, 0, dpr, 0, 0);

	// Embers: climb, sway, cool through three colors and burn out
	const drag = Math.exp(-1.6 * dt), wind = WIND * mouse.energy * 900;
	for (let i = 0; i < EMBER_COUNT; i++) {
		eage[i] += dt;
		ey[i] -= espd[i] * dt;
		const r = (ey0[i] - ey[i]) / erise[i];
		if (r >= 1) { spawn(i, false); continue; }
		if (wind > 1) {
			const dx = ex[i] - mouse.x, dy = ey[i] - mouse.y, dd = dx * dx + dy * dy;
			if (dd < 32400 && dd > 1) {
				const dist = Math.sqrt(dd);
				evx[i] += (dx / dist) * (1 - dist / 180) * wind * dt;
				ey[i] -= (1 - dist / 180) * wind * 0.15 * dt;
			}
		}
		evx[i] *= drag;
		ex[i] += (evx[i] + Math.sin(time * 0.8 + eph[i]) * SWAY) * dt;
		if (ex[i] < -20) ex[i] += w + 40; else if (ex[i] > w + 20) ex[i] -= w + 40;
		const a = Math.min(1, eage[i] / 0.8) * (1 - r * r) * (0.7 + 0.3 * Math.sin(time * 3 + eph[i] * 5)) * calm(ex[i]) * lit;
		if (a < 0.02) continue;
		const d = esz[i] * (1 - r * 0.5);
		ctx.globalAlpha = a;
		ctx.drawImage(emberSprites[r < 0.3 ? 0 : r < 0.65 ? 1 : 2], ex[i] - d / 2, ey[i] - d / 2, d, d);
	}

	// Tap bursts
	const grav = 60 * dt;
	for (let i = 0; i < bcount; i++) {
		blife[i] -= dt;
		if (blife[i] <= 0) {
			const j = --bcount;
			bx[i] = bx[j]; by[i] = by[j]; bvx[i] = bvx[j]; bvy[i] = bvy[j]; blife[i] = blife[j]; bsz[i] = bsz[j];
			i--;
			continue;
		}
		bvx[i] *= drag; bvy[i] = bvy[i] * drag + grav;
		bx[i] += bvx[i] * dt; by[i] += bvy[i] * dt;
		const f = Math.min(1, blife[i] / 1.2);
		ctx.globalAlpha = f * lit * Math.max(0.35, calm(bx[i]));
		const d = bsz[i] * (0.6 + 0.4 * f);
		ctx.drawImage(emberSprites[f > 0.6 ? 0 : 1], bx[i] - d / 2, by[i] - d / 2, d, d);
	}
	ctx.globalAlpha = 1;
	ctx.globalCompositeOperation = 'source-over';
}

function move(x, y) {
	if (mouse.x > -9000) mouse.energy = Math.min(1, mouse.energy + Math.hypot(x - mouse.x, y - mouse.y) / 60);
	mouse.x = x; mouse.y = y;
}

self.onmessage = (e) => {
	const d = e.data;
	switch (d.type) {
		case 'init':
			canvas = d.canvas;
			ctx = canvas.getContext('2d');
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			reduced = !!d.reducedMotion;
			applyTheme(d.theme);
			buildSprites();
			size(0, 0);
			requestAnimationFrame(frame);
			break;
		case 'resize': {
			const ow = w, oh = h;
			w = d.width; h = d.height; dpr = Math.min(d.dpr || 1, 1);
			if (canvas) size(ow, oh);
			break;
		}
		case 'theme':
			applyTheme(d);
			break;
		case 'motion':
			reduced = !!d.reducedMotion;
			break;
		case 'mousemove':
			move(d.x, d.y);
			break;
		case 'touchmove':
			if (d.touches && d.touches.length) move(d.touches[0].x, d.touches[0].y);
			break;
		case 'mousedown':
			if (!reduced && BURST_SIZE > 0) burst(d.x, d.y);
			break;
	}
};
